        return res

#include <vector>
#include <algorithm>
#include <numeric>

class Solution {
public:
    std::vector<int> minSubsequence(std::vector<int>& nums) {
        std::sort(nums.rbegin(), nums.rend());
        int total = std::accumulate(nums.begin(), nums.end(), 0);
        int subSum = 0;
        std::vector<int> res;
        for (int x : nums) {
            subSum += x;
            res.push_back(x);
            if (subSum > total - subSum) break;
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> minSubsequence(int[] nums) {
        Arrays.sort(nums);
        int total = 0;
        for (int x : nums) total += x;
        int subSum = 0;
        List<Integer> res = new ArrayList<>();
        for (int i = nums.length - 1; i >= 0; i--) {
            subSum += nums[i];
            res.add(nums[i]);
            if (subSum > total - subSum) break;
        }
        return res;
    }
}

var minSubsequence = function(nums) {
    nums.sort((a, b) => b - a);
    const total = nums.reduce((acc, v) => acc + v, 0);
    let subSum = 0;
    const res = [];
    for (const x of nums) {
        subSum += x;
        res.push(x);
        if (subSum > total - subSum) break;
    }
    return res;
};
